Code.Terraform:
```hcl
resource "cloudflare_workers_script" "example" {
  account_id  = "<ACCOUNT_ID>"
  script_name = "example-worker"
  content     = file("worker.js")

  bindings = [{
    name = "API_TOKEN"
    type = "secret_text" # Critical: stores the value encrypted instead of plain_text
    text = var.api_token
  }]
}
```
